select * from (select case when discount >= 0.41 then 'high' when discount >= 0.13 then 'mid' else 'low' end as discount_bucket, max(discount) - min(discount) as discount_range, sort_array(collect_set(status)) as status_list from orders group by case when discount >= 0.41 then 'high' when discount >= 0.13 then 'mid' else 'low' end) as agg where discount_range > 30 order by discount_bucket asc, discount_range asc limit 50;
